from collections import deque
class Solution:
    def minimumLevel(self, root):
        q = deque([root])
        level, best, bestSum = 1, 1, float('inf')
        while q:
            s = 0
            for _ in range(len(q)):
                node = q.popleft()
                s += node.val
                if node.left: q.append(node.left)
                if node.right: q.append(node.right)
            if s < bestSum:
                bestSum, best = s, level
            level += 1
        return best

