class Solution {
public:
    int minimumLevel(TreeNode* root) {
        queue<TreeNode*> q; q.push(root);
        int level = 1, best = 1; long long bestSum = LLONG_MAX;
        while (!q.empty()) {
            int sz = q.size(); long long s = 0;
            for (int i = 0; i < sz; i++) {
                TreeNode* n = q.front(); q.pop(); s += n->val;
                if (n->left) q.push(n->left);
                if (n->right) q.push(n->right);
            }
            if (s < bestSum) { bestSum = s; best = level; }
            level++;
        }
        return best;
    }
};

