class Solution {
    List<Long> sums = new ArrayList<>();
    void go(TreeNode n, int d) {
        if (n == null) return;
        if (d == sums.size()) sums.add(0L);
        sums.set(d, sums.get(d) + n.val);
        go(n.left, d + 1);
        go(n.right, d + 1);
    }
    public int minimumLevel(TreeNode root) {
        go(root, 0);
        int best = 0;
        for (int i = 1; i < sums.size(); i++)
            if (sums.get(i) < sums.get(best)) best = i;
        return best + 1;
    }
}

